double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad)
{
    const int n_w1 = n_hidden * n_in;
    const int off_b1 = n_w1;
    const int off_w2 = off_b1 + n_hidden;
    const int off_b2 = off_w2 + n_hidden;
    const int n_total = off_b2 + 1;

    for (int i = 0; i < n_total; ++i) grad[i] = 0.0;

    double loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + (long)s * n_in;
        const double yv = y[s];

        // Forward pass
        double z = params[off_b2];
        for (int j = 0; j < n_hidden; ++j) {
            double a = params[off_b1 + j];
            const double* w1row = params + (long)j * n_in;
            for (int k = 0; k < n_in; ++k) a += w1row[k] * x[k];
            z += params[off_w2 + j] * std::tanh(a);
        }

        const double p = 1.0 / (1.0 + std::exp(-z));

        // Stable log terms:
        // log(p)   = -softplus(-z)
        // log(1-p) = -z - softplus(-z)
        double t = -z;
        double softplus;
        if (t > 0.0) softplus = t + std::log1p(std::exp(-t));
        else         softplus = std::log1p(std::exp(t));

        loss += yv * softplus + (1.0 - yv) * (z + softplus);

        // Backward pass: dL_i/dz = p - y
        const double dz = p - yv;

        grad[off_b2] += dz;

        for (int j = 0; j < n_hidden; ++j) {
            const double h = std::tanh(params[off_b1 + j]
                                       + [&]() {
                                             double acc = 0.0;
                                             const double* wr = params + (long)j * n_in;
                                             for (int k = 0; k < n_in; ++k) acc += wr[k] * x[k];
                                             return acc;
                                         }());
            grad[off_w2 + j] += dz * h;

            const double da = dz * params[off_w2 + j] * (1.0 - h * h);
            grad[off_b1 + j] += da;

            double* grow = grad + (long)j * n_in;
            for (int k = 0; k < n_in; ++k) grow[k] += da * x[k];
        }
    }

    const double inv = 1.0 / (double)n_samples;
    for (int i = 0; i < n_total; ++i) grad[i] *= inv;

    return loss * inv;
}
